package app.mini.hub.android.ui

import android.content.Context
import org.json.JSONObject

/**
 * Parsed view of assets/licenses/index.json, generated by native/compliance/build-notices.ps1.
 * Pure data; no network, no user data. Kept free of Compose so it is unit-testable.
 */
data class ThirdPartyNotice(
    val name: String,
    val version: String,
    val license: String,
    val component: String,
    val notes: String?,
    val textPaths: List<String>,
)

data class ThirdPartyNoticeIndex(
    val disclaimer: String,
    val gitCommit: String,
    val generated: String,
    val components: List<ThirdPartyNotice>,
    val canonicalTexts: Map<String, String>,
    val unknownLicense: List<String>,
    val missingText: List<String>,
) {
    /** Components grouped by where they live in the build, in a stable display order. */
    fun grouped(): List<Pair<String, List<ThirdPartyNotice>>> {
        fun bucket(n: ThirdPartyNotice): String = when {
            n.component.startsWith("libgojni.so") -> "Phone-local messaging runtime (Go)"
            n.component.startsWith("Android app") -> "Android app libraries"
            n.component.contains("model", ignoreCase = true) || n.name.contains("model", ignoreCase = true) -> "On-device AI model (not bundled)"
            n.component.contains("font", ignoreCase = true) -> "Fonts"
            else -> "Other components"
        }
        val order = listOf(
            "Phone-local messaging runtime (Go)",
            "Android app libraries",
            "Fonts",
            "On-device AI model (not bundled)",
            "Other components",
        )
        return components.groupBy(::bucket)
            .toList()
            .sortedBy { order.indexOf(it.first).let { i -> if (i < 0) order.size else i } }
            .map { (k, v) -> k to v.sortedBy { it.name.lowercase() } }
    }

    companion object {
        const val ASSET_INDEX = "licenses/index.json"

        fun parse(json: String): ThirdPartyNoticeIndex {
            val root = JSONObject(json)
            val comps = root.optJSONArray("components")
            val list = buildList {
                if (comps != null) for (i in 0 until comps.length()) {
                    val c = comps.getJSONObject(i)
                    val files = c.optJSONArray("files")
                    val paths = buildList {
                        if (files != null) for (j in 0 until files.length()) {
                            val f = files.opt(j)
                            when (f) {
                                is JSONObject -> f.optString("path").takeIf { it.isNotBlank() }?.let(::add)
                                is String -> if (f.isNotBlank()) add(f)
                            }
                        }
                    }
                    add(
                        ThirdPartyNotice(
                            name = c.optString("name"),
                            version = c.optString("version"),
                            license = c.optString("license"),
                            component = c.optString("component"),
                            notes = c.optString("notes").takeIf { it.isNotBlank() && it != "null" },
                            textPaths = paths.distinct(),
                        ),
                    )
                }
            }
            val canon = root.optJSONObject("canonical_texts")
            val canonMap = buildMap {
                canon?.keys()?.forEach { k -> canon.optJSONObject(k)?.optString("path")?.let { put(k, it) } }
            }
            val gaps = root.optJSONObject("gaps")
            fun arr(name: String) = buildList {
                val a = gaps?.optJSONArray(name)
                if (a != null) for (i in 0 until a.length()) add(a.getString(i))
            }
            return ThirdPartyNoticeIndex(
                disclaimer = root.optString("disclaimer"),
                gitCommit = root.optString("git_commit"),
                generated = root.optString("generated"),
                components = list,
                canonicalTexts = canonMap,
                unknownLicense = arr("unknown_license"),
                missingText = arr("no_text"),
            )
        }

        fun load(context: Context): ThirdPartyNoticeIndex? = runCatching {
            context.assets.open(ASSET_INDEX).bufferedReader().use { parse(it.readText()) }
        }.getOrNull()

        fun readText(context: Context, path: String): String? = runCatching {
            context.assets.open("licenses/$path").bufferedReader().use { it.readText() }
        }.getOrNull()
    }
}
